pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint88 times) public {
        times = uint88(bound(times, 2, 20));
        address player = address(0x1234);
        vm.deal(player, (uint256(times) + 1) * 10 ether);

        vm.startPrank(player);
        for (uint88 i = 0; i < times; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();

        uint256 pot = c.pot();
        assertTrue(pot == 0 || pot % 10 == 0);
    }
}
